  <section class="profile-header"><div class="profile-identity">${avatar()}<div><div class="profile-name">${esc(state.profile.name)} ${state.profile.badge?badge():''}</div><div class="profile-subtitle"><span>${esc(state.profile.subtitle)}</span><span class="private-tag">PRIVATE WORKSPACE</span></div></div></div><div class="profile-actions"><span class="date-label">${icon('calendar')}${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span><button class="btn btn-secondary" data-action="profile">${icon('edit')}<span class="label">Edit profile</span></button></div></section>
